const need=(ok,message)=>{if(!ok)throw Error(message);};
const rounded=(ctx,x,y,w,h,r)=>{ctx.beginPath();if(ctx.roundRect)ctx.roundRect(x,y,w,h,Math.min(r,w/2,h/2));else ctx.rect(x,y,w,h);};
function drawFit(ctx,img,x,y,w,h,mode='cover'){const scale=mode==='contain'?Math.min(w/img.naturalWidth,h/img.naturalHeight):Math.max(w/img.naturalWidth,h/img.naturalHeight),dw=img.naturalWidth*scale,dh=img.naturalHeight*scale;ctx.save();ctx.beginPath();ctx.rect(x,y,w,h);ctx.clip();ctx.drawImage(img,x+(w-dw)/2,y+(h-dh)/2,dw,dh);ctx.restore();}
function wrapped(ctx,text,width){const words=text.split(/\s+/u),lines=[];let line='';for(let word of words){while(ctx.measureText(word).width>width&&word.length>1){let i=1;while(i<word.length&&ctx.measureText(word.slice(0,i+1)).width<=width)i++;if(line){lines.push(line);line='';}lines.push(word.slice(0,i));word=word.slice(i);}const next=line?line+' '+word:word;if(ctx.measureText(next).width>width&&line){lines.push(line);line=word;}else line=next;}if(line)lines.push(line);return lines;}
function outputImage(out,c,blob,{name='nepocore-image.png',note='',extra=''}={}){const url=URL.createObjectURL(blob);result(out,{html:`<div class="image-preview"><img alt="Your generated image" width="${c.width}" height="${c.height}"></div><div class="image-meta"><span>${c.width} × ${c.height} px</span><span>${bytes(blob.size)}</span></div><div class="result-actions"><button class="btn primary" data-download>${icon('download')} Download PNG</button>${extra}</div>`,note});out.querySelector('img').src=url;out.querySelector('[data-download]').onclick=()=>download(blob,name);return url;}
