   if(id==='meme-generator'){need(v.top.length<=180&&v.bottom.length<=180,'Keep each caption under 180 characters.');let fs=+v.font;x.font=`900 ${fs}px Impact, Arial, sans-serif`;x.textAlign='center';x.textBaseline='top';x.lineJoin='round';x.lineWidth=Math.max(2,fs*.075);x.strokeStyle='#111';x.fillStyle='#fff';const draw=(txt,bottom)=>{const lines=wrapped(x,txt.toUpperCase(),w-36),step=fs*1.12,y=bottom?h-20-lines.length*step:20;need(lines.length*step<h*.45,'The caption is too long for this image. Reduce the text size or shorten it.');lines.forEach((line,i)=>{x.strokeText(line,w/2,y+i*step);x.fillText(line,w/2,y+i*step);});};draw(v.top,false);draw(v.bottom,true);}
